mapper.select:
select id, trade_time, counterparty_account_no, type, amount, description from transaction_record where 1 = 1
and account_id = #{query.accountId}
and type = #{query.type}
and trade_time >= #{query.startTime}
and trade_time <= #{query.endTime}
order by trade_time desc

SELECT COUNT(1)
FROM transaction_record tr
JOIN account a ON tr.account_id = a.id
WHERE 1 = 1


    AND a.account_no = #{query.accountNo}


    AND tr.type = #{query.type}


    AND tr.trade_time >= #{query.startTime}


    AND tr.trade_time <= #{query.endTime}

select
COALESCE(
SUM(
case
when #{query.txnType} = '支出' then ABS(amount)
else amount
end
), 0
)
from transaction_record
where 1 = 1

    and account_id = #{query.accountId}


    and type = #{query.txnType}


    and trade_time  >=  #{query.startTime}


    and trade_time  <=  #{query.endTime}

select COUNT(1)
from transaction_record
where 1 = 1

    and account_id = #{query.accountId}


    and type = #{query.txnType}


    and trade_time  >=  #{query.startTime}


    and trade_time  <=  #{query.endTime}

select
DATE_FORMAT(trade_time, '%Y-%m-%d %H:%i:%s') as label,
ABS(amount) as value
from transaction_record
where 1 = 1

    and account_id = #{query.accountId}


    and type = #{query.txnType}


    and trade_time  >=  #{query.startTime}


    and trade_time  <=  #{query.endTime}

order by ABS(amount) desc, trade_time desc
limit 1

select
DATE_FORMAT(trade_time, '%Y-%m') as label,
COALESCE(
SUM(
case
when type = '支出' then ABS(amount)
else amount
end
), 0
) as value
from transaction_record
where 1 = 1

    and account_id = #{query.accountId}


    and type = #{query.txnType}


    and trade_time  >=  #{query.startTime}


    and trade_time  <=  #{query.endTime}

group by DATE_FORMAT(trade_time, '%Y-%m')
order by DATE_FORMAT(trade_time, '%Y-%m') asc
